	{ id = 59, version = "0.6.0", module = "tweaks",
		en = { "Combo points: coloured, on your target", "Forever's personal resource display shows combo points now, so LefthyTools' own row is gone: the colouring by count goes onto Blizzard's. New: a small gem like the display's right of your target's level on its nameplate, in that colour, with the number of points." },
		de = { "Combopunkte: gefärbt, an deinem Ziel", "Die persönliche Ressourcenanzeige in Forever zeigt jetzt Combopunkte, deshalb ist die eigene Reihe von LefthyTools weg: das Färben nach Anzahl gilt jetzt für Blizzards. Neu: ein kleiner Combopunkt wie in der Anzeige rechts neben dem Level an der Namensplakette deines Ziels, in dieser Farbe, mit der Anzahl der Punkte." } },
	{ id = 60, version = "0.6.0", module = "tweaks",
		en = { "Bags: the clean-up button is back", "Forever's latest patch removed the bags' clean-up button, with mouse and keyboard and in gamepad mode. It's back, at the left of the bags' search box." },
		de = { "Taschen: Aufräumen-Knopf ist zurück", "Mit dem letzten Forever-Patch fehlte der Aufräumen-Knopf der Taschen, mit Maus und Tastatur wie im Gamepad-Modus. Er ist zurück, links neben dem Suchfeld der Taschen." } },
	{ id = 61, version = "0.6.0", module = "beacon",
		en = { "Watch your friends' fights live", "A small live view of a friend's fight: them in the middle on the map, the mobs around them, their group and other players nearby, what they're casting. Click their dot on the world map to open it (again to close), pick them from the spyglass button on the minimap, or /lefthy stream watch <name>. On a cinematic flight one friend's fight opens by itself, and the top bar has a Watch button for each friend. Drag the window's corner to resize it. A tiny red dot by the minimap's calendar button shows when friends watch you; sharing can be switched off in the Beacon settings." },
		de = { "Kämpfe deiner Freunde live ansehen", "Eine kleine Live-Ansicht vom Kampf eines Freundes: er in der Mitte auf der Karte, die Mobs um ihn herum, seine Gruppe und andere Spieler in der Nähe, was er gerade wirkt. Klick seinen Punkt auf der Weltkarte an, um sie zu öffnen (nochmal zum Schließen), wähl ihn am Fernrohr-Button an der Minimap, oder /lefthy stream watch <name>. Auf einem Flug im Kinomodus öffnet sich der Kampf eines Freundes von selbst, und die obere Leiste hat für jeden Freund einen Zuschauen-Button. Zieh an der Ecke des Fensters, um die Größe zu ändern. Ein winziger roter Punkt am Kalender-Button der Minimap zeigt, wenn Freunde dir zuschauen; das Teilen lässt sich in den Beacon-Einstellungen abschalten." } },
	{ id = 62, version = "0.6.0", module = "chronicle",
		en = { "Friends' news even when they're offline", "Battle.net only reaches friends who are online, so now your friends' LefthyTools pass each other's journals on: whoever is online brings you the news, days and numbers of those who aren't, and yours reach them the same way. Only to people who have that player as a Battle.net friend too. The Friends page lists who isn't online, when they last played and their latest news; a blue dot on the book says there's something new." },
		de = { "Neues von Freunden, auch wenn offline", "Battle.net erreicht nur Freunde, die online sind, deshalb geben die LefthyTools deiner Freunde ihre Tagebücher jetzt untereinander weiter: wer online ist, bringt dir die Neuigkeiten, Tage und Zahlen derer mit, die es nicht sind, und deine erreichen sie genauso. Nur an Leute, die diesen Spieler auch als Battle.net-Freund haben. Die Freunde-Seite zeigt, wer nicht online ist, wann er zuletzt gespielt hat und seine letzten Neuigkeiten; ein blauer Punkt am Buch sagt, dass es Neues gibt." } },
	{ id = 63, version = "0.6.0", module = "chronicle",
		en = { "Compare: all friends in every graph", "A new Compare page: you and every friend in every graph, a line each: level, time played, XP, quests, kills, deaths, gold, distance, bosses and rares, time AFK and jumps over 7, 14 or 30 days. Plus this week's leaderboard with the Martin award, a hall of fame and records. Share posts a ranking in Lefthy chat." },
		de = { "Vergleich: alle Freunde in jedem Graphen", "Eine neue Vergleich-Seite: du und jeder Freund in jedem Graphen, eine Linie pro Person: Level, Spielzeit, Erfahrung, Quests, Kills, Tode, Gold, Strecke, Bosse und Rares, Zeit AFK und Sprünge über 7, 14 oder 30 Tage. Dazu die Bestenliste der Woche mit dem Martin-Preis, eine Ruhmeshalle und Rekorde. Teilen postet eine Rangliste im Lefthy-Chat." } },
	{ id = 64, version = "0.6.0", module = "chronicle",
		en = { "While you were away, and a weekly recap", "A minute after you log in, a chat line per friend with what they did since you last played. And once a week, the first time you play, last week's leaderboard in chat." },
		de = { "Was du verpasst hast, und Wochenbilanz", "Eine Minute nach dem Einloggen eine Chatzeile pro Freund mit dem, was er seit deinem letzten Spielen gemacht hat. Und einmal pro Woche, beim ersten Spielen, die Bestenliste der letzten Woche im Chat." } },
	{ id = 65, version = "0.6.0", module = "chronicle",
		en = { "AFK and jumps: for all your characters", "Some numbers are about the player, not the character: the Martin tracker (time AFK) and jumps now count all your characters together, in a new All your characters section of the statistics. The Compare page and the leaderboards go per person too: an alt's quests, kills and time count for its player." },
		de = { "AFK und Sprünge: alle Charaktere", "Manche Zahlen gehören zum Spieler, nicht zum Charakter: der Martin-Tracker (Zeit AFK) und die Sprünge zählen jetzt alle deine Charaktere zusammen, in einem neuen Abschnitt Alle deine Charaktere in der Statistik. Die Vergleich-Seite und die Bestenlisten gehen auch nach Person: Quests, Kills und Zeit eines Twinks zählen für seinen Spieler." } },
	{ id = 66, version = "0.6.0", module = "mirage",
		en = { "Mirage: pause from the minimap", "A button on the minimap's edge while Mirage is on: click it to pause fading (the interface stays, the icon greys out), click again to fade when idle again. Right-click opens Mirage's settings. /mirage pause does the same." },
		de = { "Mirage: Pause an der Minimap", "Ein Button am Rand der Minimap, solange Mirage an ist: ein Klick pausiert das Ausblenden (das Interface bleibt, das Symbol wird grau), ein zweiter blendet wieder aus, wenn du nichts tust. Rechtsklick öffnet die Einstellungen von Mirage. /mirage pause macht dasselbe." } },
	{ id = 67, version = "0.6.0", module = "tweaks",
		en = { "Flights: six friends, top and bottom", "On a cinematic flight three friends fit in the top bar and three more in the bottom one; the time left moves to its right end while they're there." },
		de = { "Flüge: sechs Freunde, oben und unten", "Auf einem Flug im Kinomodus passen drei Freunde in die obere Leiste und drei weitere in die untere; die Restzeit rückt dann an ihr rechtes Ende." } },
	{ id = 68, version = "0.6.0", module = "tweaks",
		en = { "Flights: shared items can be hovered", "An item a friend shows you during a cinematic flight now has its tooltip when you hover it in the subtitles, and a click opens it (the film waits until you close it)." },
		de = { "Flüge: geteilte Items mit Tooltip", "Ein Item, das dir ein Freund während eines Flugs im Kinomodus zeigt, hat jetzt seinen Tooltip, wenn du in den Untertiteln mit der Maus darauf zeigst, und ein Klick öffnet es (der Film wartet, bis du es schließt)." } },
	{ id = 69, version = "0.6.0", module = "tweaks",
		en = { "Combo gem: display's look, your place", "The combo point gem on your target's nameplate is now copied from the personal resource display's own, border and all, and smaller. Three new sliders set its size and where it sits; while you move them it shows on your target." },
		de = { "Combopunkt: Anzeige-Look, dein Platz", "Der Combopunkt an der Namensplakette deines Ziels ist jetzt eine Kopie des Punkts der persönlichen Ressourcenanzeige, mit Rand, und kleiner. Drei neue Regler bestimmen Größe und Position; während du sie bewegst, zeigt er sich an deinem Ziel." } },
	{ id = 70, version = "0.6.0", module = "tweaks",
		en = { "Combo gem: place it without a mob", "Try it (Misc Tweaks, or /lefthy tweaks combopos) opens a small window with a nameplate: drag the combo point gem where you want it, the mouse wheel over it changes its size, the arrows nudge it. No mob needed, and the settings can be closed." },
		de = { "Combopunkt: platzieren ohne Mob", "Ausprobieren (Misc Tweaks, oder /lefthy tweaks combopos) öffnet ein kleines Fenster mit einer Namensplakette: zieh den Combopunkt dorthin, wo du ihn haben willst, das Mausrad darüber ändert seine Größe, die Pfeile verschieben ihn. Kein Mob nötig, und die Einstellungen können zu sein." } },
	{ id = 71, version = "0.6.0", module = "chronicle",
		en = { "Friends' journals: more reliable", "A journal that arrived only in part is asked for again instead of counting as complete, everything is offered again every few minutes in case an offer got lost, and answering a friend's request no longer stutters the game. Players who are no longer your Battle.net friends drop out of the book, and so do characters with nothing in 60 days." },
		de = { "Freunde-Tagebücher: zuverlässiger", "Ein Tagebuch, das nur zum Teil angekommen ist, wird nochmal angefragt, statt als vollständig zu gelten, alles wird alle paar Minuten neu angeboten, falls ein Angebot verloren ging, und eine Anfrage eines Freundes zu beantworten lässt das Spiel nicht mehr ruckeln. Wer nicht mehr dein Battle.net-Freund ist, fällt aus dem Buch, genauso Charaktere ohne etwas in 60 Tagen." } },
	{ id = 72, version = "0.6.0", module = "chronicle",
		en = { "Friends at a glance, news on its own tab", "The Friends tab shows everyone in two tables: who's online (level, where they are, what they're doing) and who isn't (when they last played, this week's time, their latest news). Hover a row for all of it, click it for their graphs. What everyone did has a tab of its own, News, which shows how much is new: no more scrolling past the list to get to it." },
		de = { "Freunde-Überblick, eigener Tab Neues","Der Freunde-Tab zeigt alle in zwei Tabellen: wer online ist (Level, wo, was er gerade macht) und wer nicht (wann zuletzt gespielt, Spielzeit diese Woche, das Neueste). Fahr über eine Zeile für alles, klick sie für ihre Graphen. Was alle gemacht haben, hat einen eigenen Tab, Neues, der zeigt, wie viel neu ist: kein Scrollen mehr an der Liste vorbei." } },
	{ id = 73, version = "0.6.0", module = "chronicle",
		en = { "Compare: pick any graph, with symbols", "The big chart at the top of the Compare page isn't only level any more: icons above it switch to time played, XP, quests, kills, deaths, gold, distance, bosses and rares, time AFK or jumps, per day or adding up. Symbols on the lines show everyone's big moments: a skull where someone died, a dragon for a boss, every tenth level, dungeons, rares, epic loot and more. Hover a symbol for what happened, a day for everyone's numbers, or click any small chart to show it big." },
		de = { "Vergleich: jeder Graph, mit Symbolen", "Der große Graph oben auf der Vergleich-Seite zeigt nicht mehr nur Level: Symbole darüber wechseln zu Spielzeit, EP, Quests, Kills, Toden, Gold, Strecke, Bossen und Rares, Zeit AFK oder Sprüngen, pro Tag oder zusammengezählt. Symbole auf den Linien zeigen die großen Momente: ein Totenkopf, wo jemand gestorben ist, ein Drache für einen Boss, jedes zehnte Level, Dungeons, Rares, epische Items und mehr. Fahr über ein Symbol, um zu sehen, was passiert ist, über einen Tag für die Zahlen aller, oder klick einen kleinen Graphen an, um ihn groß zu zeigen." } },
	{ id = 74, version = "0.6.0", module = "beacon",
		en = { "Beacon: fixes from a check-up", "With many WoW friends who don't run LefthyTools, the greetings to them no longer hold up your chat lines or Need answers. A friend's first message right after they come online no longer gets lost. Error reports stay saved until they've really gone out. Switching map pings off removes the markers already up, and a friend going away takes theirs along. No more death alert when a friend switches sharing on while already dead, and the enemy count is right again after switching Beacon off and on." },
		de = { "Beacon: Korrekturen nach Durchsicht", "Bei vielen WoW-Freunden ohne LefthyTools halten die Grüße an sie deine Chatzeilen und Bedarf-Antworten nicht mehr auf. Die erste Nachricht eines Freundes direkt nach dem Einloggen geht nicht mehr verloren. Fehlerberichte bleiben gespeichert, bis sie wirklich raus sind. Kartenpings ausschalten entfernt auch die Markierungen, die schon da sind, und ein Freund, der weg ist, nimmt seine mit. Kein Todesalarm mehr, wenn ein Freund das Teilen einschaltet, während er schon tot ist, und die Gegnerzahl stimmt wieder nach Beacon aus und an." } },
	{ id = 75, version = "0.6.0", module = "tweaks",
		en = { "Bags and flights: small fixes", "The bags' search box no longer moves over twice when the bags open without the game placing it again (after Alt+Z, say). In gamepad mode, clicking an item in a flight's subtitles shows its tooltip without risking blocked buttons later. A flight not taken from the flight map (a quest's) no longer gets the previous flight's destination and time." },
		de = { "Taschen und Flüge: kleine Korrekturen", "Das Suchfeld der Taschen rutscht nicht mehr doppelt zur Seite, wenn die Taschen aufgehen, ohne dass das Spiel es neu setzt (etwa nach Alt+Z). Im Gamepad-Modus zeigt ein Klick auf ein Item in den Untertiteln eines Flugs seinen Tooltip, ohne dass später Buttons blockiert werden können. Ein Flug, der nicht über die Flugkarte gebucht wurde (der einer Quest), bekommt nicht mehr Ziel und Zeit des letzten Flugs." } },
	{ id = 76, version = "0.6.0", module = "mirage",
		en = { "Mirage: minimap lists stay in view", "A minimap button's list, like the stream spyglass's, keeps the minimap in view while it's open, so it no longer fades away under your mouse. And pressing Toggle Minimap during a cinematic flight no longer switches the minimap off for good." },
		de = { "Mirage: Minimap-Listen bleiben sichtbar", "Die Liste eines Minimap-Buttons, etwa die vom Fernrohr für Streams, hält die Minimap sichtbar, solange sie offen ist, sie blendet also nicht mehr unter deiner Maus aus. Und Minimap umschalten während eines Flugs im Kinomodus schaltet die Minimap nicht mehr dauerhaft aus." } },
	{ id = 77, version = "0.6.0", module = "tweaks",
		en = { "Combo points: dots in the health bar", "The combo point gem beside your target's level is gone. Instead, small dots sit in the middle of its health bar, one for each point you can have: lit ones in the colour of your points, the rest dark, each on a dark ring so it reads on a red bar. They take no room, so nothing else on the nameplate moves. A slider sets their size, and Try it shows them counting up on a stand-in nameplate." },
		de = { "Combopunkte: Punkte in der Leiste", "Der Combopunkt neben dem Level deines Ziels ist weg. Stattdessen sitzen kleine Punkte in der Mitte seiner Lebensleiste, einer für jeden Punkt, den du haben kannst: die aktiven in der Farbe deiner Punkte, die übrigen dunkel, jeder auf einem dunklen Ring, damit er auch auf roter Leiste gut lesbar ist. Sie brauchen keinen Platz, an der Namensplakette verschiebt sich also nichts. Ein Regler bestimmt ihre Größe, und Ausprobieren zeigt sie hochzählend an einer Beispiel-Namensplakette." } },
	{ id = 78, version = "0.6.0", module = "tweaks",
		en = { "Retail unit frames, if you want them", "Forever's latest patch drew the player, target, focus, party and pet frames in a classic style. A new Misc Tweaks option, off by default, brings back retail's: their art, bars and layout (the game still has them). Switching it off takes a /reload." },
		de = { "Einheitenfenster wie in Retail", "Seit Forevers letztem Patch sind die Fenster für Spieler, Ziel, Fokus, Gruppe und Pet im Classic-Stil. Eine neue Option in Misc Tweaks, standardmäßig aus, holt die aus Retail zurück: Grafik, Leisten und Anordnung (das Spiel hat sie noch). Zum Ausschalten ist ein /reload nötig." } },
	{ id = 79, version = "0.6.0", module = "beacon",
		en = { "Lefthy chat is now LTC, with /ltc", "Lefthy chat is called LTC (LefthyTools chat) now: lines show as [LTC] [Anna], the chat box says LTC:, and /ltc works like /l. Friends who haven't updated still see [Lefthy]; nothing else changes." },
		de = { "Lefthy-Chat heißt jetzt LTC, mit /ltc", "Der Lefthy-Chat heißt jetzt LTC (LefthyTools-Chat): Zeilen erscheinen als [LTC] [Anna], im Chatfeld steht LTC:, und /ltc funktioniert wie /l. Freunde ohne Update sehen weiter [Lefthy]; sonst ändert sich nichts." } },
	{ id = 80, version = "0.6.0", module = "beacon",
		en = { "Fight stream: health, estimated", "A friend's stream now shows their health: a green bar over their power bar, with a percent beside it. The game hides health from addons, so it's added up from the hits and heals they take and set right whenever they're back at full health, which is why it says ~80%: about. Right after a /reload (in a fight, say) it isn't known for a while: then it says ~?, and hovering tells why. Friends need this update to send theirs." },
		de = { "Kampf-Stream: Leben, geschätzt", "Der Stream eines Freundes zeigt jetzt sein Leben: eine grüne Leiste über der Ressourcenleiste, mit Prozent daneben. Das Spiel verbirgt das Leben vor Addons, deshalb wird es aus den Treffern und Heilungen zusammengezählt und jedes Mal korrigiert, wenn er wieder volles Leben hat; daher ~80%: ungefähr. Direkt nach einem /reload (etwa im Kampf) ist es eine Weile nicht bekannt: dann steht dort ~?, und der Tooltip sagt, warum. Freunde brauchen dieses Update, um ihres zu senden." } },
	{ id = 81, version = "0.6.0", module = "beacon",
		en = { "Fight stream: hits, heals, XP and loot", "What happens to a friend floats up in their stream: the hits they take in red, heals in green (bigger when big), a dodge or miss, XP rising from the mob that died, and green or better loot with its icon and name. Their kills since you opened the window count at the top right. Your own stream and the demo show it too." },
		de = { "Kampf-Stream: Treffer, Heilung, EP, Loot", "Was einem Freund passiert, steigt in seinem Stream auf: Treffer, die er abbekommt, in Rot, Heilungen in Grün (größer, wenn sie groß sind), ein Ausweichen oder Verfehlen, EP, die vom gestorbenen Mob aufsteigen, und grüner oder besserer Loot mit Symbol und Namen. Seine Kills, seit du das Fenster geöffnet hast, stehen oben rechts. Dein eigener Stream und die Demo zeigen es auch." } },
	{ id = 82, version = "0.6.0", module = "beacon",
		en = { "Fight stream: casting mobs glow again", "Forever hides what a mob casts, which also hid that it was casting: the purple glow on its dot never came. The game still says when a cast begins and ends, so the glow is back, and the tooltip and bottom line say it's casting a spell (which one stays hidden)." },
		de = { "Kampf-Stream: Zaubernde Mobs leuchten", "Forever verbirgt, was ein Mob zaubert, und damit auch, dass er zaubert: das violette Leuchten an seinem Punkt kam nie. Das Spiel sagt aber noch, wann ein Zauber beginnt und endet, also ist das Leuchten zurück, und Tooltip und unterste Zeile sagen, dass er einen Zauber wirkt (welchen, bleibt verborgen)." } },
	{ id = 83, version = "0.6.0", module = "beacon",
		en = { "Friends' health in tooltips and lists", "A friend's health (the same estimate as in their fight stream) now shows beside their level: on their map dot's tooltip, on the AFK screen and in a flight's bars, green, yellow below half, red below a quarter. It goes to every friend, not only to whoever watches their stream. Friends need this update to send theirs." },
		de = { "Leben der Freunde in Tooltips und Listen", "Das Leben eines Freundes (dieselbe Schätzung wie in seinem Kampf-Stream) steht jetzt neben seinem Level: im Tooltip seines Kartenpunkts, auf dem AFK-Bildschirm und in den Balken eines Flugs, grün, unter der Hälfte gelb, unter einem Viertel rot. Es geht an alle Freunde, nicht nur an die, die seinen Stream schauen. Freunde brauchen dieses Update, um ihres zu senden." } },
	{ id = 84, version = "0.6.0", module = "beacon",
		en = { "Fight stream: the enemies, with health", "Under the spells, the stream now shows the enemies fighting them (up to five) and their target, the target first with a gold edge: a small still model of each whole mob and a health bar under it. In your own stream that's their real health. In a friend's it's estimated from the hits they take, against what a mob of their level usually has, and once one of their kind is seen from full health to dead, against what their kind really has (at every level). Elites and rares say ? until then. What's learned stays with your LefthyTools. A mob your game hasn't met yet shows its initials until its model has loaded." },
		de = { "Kampf-Stream: Gegner mit Leben", "Unter den Zaubern zeigt der Stream jetzt die Gegner, die mit ihm kämpfen (bis zu fünf), und sein Ziel, das Ziel zuerst mit goldenem Rand: ein kleines, stilles Modell jedes ganzen Mobs und eine Lebensleiste darunter. In deinem eigenen Stream ist das ihr echtes Leben. In dem eines Freundes wird es geschätzt: die Treffer, die sie abbekommen, gemessen an dem, was ein Mob ihres Levels üblicherweise hat, und sobald einer ihrer Art von vollem Leben bis zum Tod gesehen wurde, an dem, was ihre Art wirklich hat (auf jedem Level). Elites und Rares zeigen bis dahin ?. Was gelernt wird, bleibt in deinem LefthyTools. Ein Mob, den dein Spiel noch nicht kennt, zeigt seine Initialen, bis sein Modell geladen ist." } },
	{ id = 85, version = "0.6.0", module = "chronicle",
		en = { "Compare: no friend counted twice", "Days a friend sends from a character their synced journal doesn't have yet, or from an older LefthyTools, now count for their BattleTag, so they no longer show up as a second person marked (friend)." },
		de = { "Vergleich: kein Freund mehr doppelt", "Tage, die ein Freund von einem Charakter schickt, den sein abgeglichenes Tagebuch noch nicht hat, oder von einem älteren LefthyTools, zählen jetzt für seinen BattleTag: er erscheint nicht mehr als zweite Person mit (Freund)." } },
	{ id = 86, version = "0.6.0", module = "chronicle",
		en = { "Chronicle: you, not one character", "Statistics, Graphs and the Timeline now add up all your characters, and each number shows once: time AFK only in the Martin tracker, no character and all-characters versions side by side. Only levels, time per level and the session you're playing stay per character. The dropdown at the top lists each person once: you, then every friend by BattleTag with their characters. A friend's graphs add up their characters too, and time AFK is back in the graphs." },
		de = { "Chronicle: du, nicht ein Charakter", "Statistiken, Grafiken und die Zeitleiste zählen jetzt alle deine Charaktere zusammen, und jede Zahl steht nur einmal da: Zeit AFK nur im Martin-Tracker, keine Charakter- und Alle-Charaktere-Werte mehr nebeneinander. Nur Level, Zeit pro Level und die laufende Session bleiben pro Charakter. Das Dropdown oben zeigt jede Person einmal: dich, dann jeden Freund nach BattleTag mit seinen Charakteren. Die Grafiken eines Freundes zählen seine Charaktere auch zusammen, und Zeit AFK ist zurück in den Grafiken." } },
	{ id = 87, version = "0.6.0", module = "chronicle",
		en = { "Friends tab: a row per friend", "Not online lists each friend once, with all their characters together (hover the row for them), and a friend who's online no longer shows up there with their other characters as well." },
		de = { "Freunde-Tab: eine Zeile pro Freund", "Nicht online zeigt jeden Freund einmal, mit allen seinen Charakteren zusammen (fahr über die Zeile für die Liste), und ein Freund, der online ist, steht dort nicht mehr zusätzlich mit seinen anderen Charakteren." } },
	{ id = 88, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: what mobs drop", "A new module that keeps track of what the mobs you kill drop. A minimap button opens a window that follows your target: your kills of that mob, the coin each brought, and every item it dropped with how many you got and its drop chance. Hover a drop for its tooltip, Shift-click to link it. The window stays open until you close it. Only kills you made on your own and looted count, so the chances hold. A setting shows a hovered enemy's drops next to the mouse. All your characters add to it; it stays on your computer. /bestiary log shows what was made of your last loot windows." },
		de = { "Bestiary: was Mobs droppen", "Ein neues Modul merkt sich, was die Mobs droppen, die du tötest. Ein Minimap-Button öffnet ein Fenster, das deinem Ziel folgt: deine Kills dieses Mobs, das Geld pro Kill und jedes Item, das er gedroppt hat, mit wie vielen du bekommen hast und der Dropchance. Fahr über einen Drop für seinen Tooltip, Shift-Klick verlinkt ihn. Das Fenster bleibt offen, bis du es schließt. Es zählen nur Kills, die du allein gemacht und gelootet hast, damit die Chancen stimmen. Eine Einstellung zeigt die Drops eines Gegners neben der Maus, wenn du über ihn fährst. Alle deine Charaktere tragen dazu bei; es bleibt auf deinem Computer. /bestiary log zeigt, was aus deinen letzten Loot-Fenstern wurde." } },
	{ id = 89, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: skinning", "What you skin is kept too, apart from the drops: per kind of mob, how often you skinned it and what came, with the chance per skinning. Skinning's pelt icon marks it in the window, the ledger and item tooltips. The window also shows the coin each kill brought on average, or no coin." },
		de = { "Bestiary: Kürschnern", "Was du kürschnerst, wird auch festgehalten, getrennt von den Drops: pro Art von Mob, wie oft du ihn gekürschnert hast und was dabei kam, mit der Chance pro Kürschnern. Das Fell-Symbol des Kürschnerns markiert es im Fenster, im Verzeichnis und in Item-Tooltips. Das Fenster zeigt außerdem das Geld pro Kill im Schnitt, oder kein Geld." } },
	{ id = 90, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: drop chances on items", "An item's tooltip, in your bags, in chat or anywhere, lists the three mobs it comes from likeliest, with the drop chance and how many kills that's from. A setting, on by default. Shift-click on the minimap button now switches the drops next to the mouse on or off." },
		de = { "Bestiary: Dropchancen an Items", "Der Tooltip eines Items, in deinen Taschen, im Chat oder sonstwo, zeigt die drei Mobs, von denen es am wahrscheinlichsten kommt, mit der Dropchance und aus wie vielen Kills. Eine Einstellung, standardmäßig an. Shift-Klick auf den Minimap-Button schaltet jetzt die Drops neben der Maus an oder aus." } },
	{ id = 91, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: the ledger, with search", "Every mob you've killed in one list: kills, level and its best drops at a glance, sorted as you like. Pick one for its slowly turning model, kills, coin, first and last kill and all its drops. The search finds mobs and items from a few of their letters. At the top: everything in all, the coin per kill and your rarest find. Open it with the book in the window, Ctrl-click on the minimap button or /bestiary ledger." },
		de = { "Bestiary: das Verzeichnis, mit Suche", "Jeder Mob, den du getötet hast, in einer Liste: Kills, Level und seine besten Drops auf einen Blick, sortiert wie du willst. Wähl einen für sein langsam drehendes Modell, Kills, Geld, ersten und letzten Kill und alle seine Drops. Die Suche findet Mobs und Items aus ein paar ihrer Buchstaben. Oben: alles zusammen, das Geld pro Kill und dein seltenster Fund. Öffnen mit dem Buch im Fenster, Strg-Klick auf den Minimap-Button oder /bestiary ledger." } },
	{ id = 92, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: world drops apart", "Random green and better gear that drops from mobs anywhere no longer sits among a mob's own drops: in the window a mob's world drops gather in one place, a map with how many, and hovering it lists them with their chances; in the ledger they're a section of their own, each with its item tooltip. Anything that has dropped from three or more kinds of mobs counts as one too. Item tooltips say when an item is a world drop." },
		de = { "Bestiary: Weltdrops getrennt", "Zufällige grüne und bessere Ausrüstung, die überall von Mobs droppt, steht nicht mehr zwischen den eigenen Drops eines Mobs: im Fenster sammeln sich die Weltdrops eines Mobs an einer Stelle, eine Karte mit ihrer Anzahl, und darüberfahren listet sie mit ihren Chancen; im Verzeichnis haben sie einen eigenen Abschnitt, jeder mit seinem Item-Tooltip. Was von drei oder mehr Arten von Mobs gedroppt ist, zählt auch dazu. Item-Tooltips sagen, wenn ein Item ein Weltdrop ist." } },
	{ id = 93, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: compare with a drop database", "The Bestiary can now show what a mob should drop, from a classic world database (CMaNGOS Classic DB) that comes with LefthyTools as an add-on of its own. Each of your drops shows the database's chance beside yours, or that it doesn't list it. In the ledger each row shows how much of a mob's loot you've found, and the picked mob has a section of what you haven't seen yet, faded, and the database's coin; hovering one shows how many you'd have expected by now. The window can show that section under your drops too, and the small card beside the mouse what a mob you haven't killed can drop (two settings, both off). Quest items are marked with a !. WoW: Forever may differ from classic, so your own numbers stay apart. A setting, on by default; restart the game once after this update." },
		de = { "Bestiary: Vergleich mit Drop-Datenbank", "Das Bestiary kann jetzt zeigen, was ein Mob droppen sollte, aus einer Classic-Weltdatenbank (CMaNGOS Classic DB), die als eigenes Addon mit LefthyTools kommt. Jeder deiner Drops zeigt die Chance der Datenbank neben deiner, oder dass sie ihn nicht kennt. Im Verzeichnis zeigt jede Zeile, wie viel vom Loot eines Mobs du gefunden hast, und der gewählte Mob hat einen Abschnitt mit dem, was du noch nicht gesehen hast, verblasst, und dem Geld laut Datenbank; darüberfahren zeigt, wie viele du bis jetzt erwartet hättest. Das Fenster kann diesen Abschnitt auch unter deinen Drops zeigen, und die kleine Karte neben der Maus, was ein Mob, den du noch nicht getötet hast, droppen kann (zwei Einstellungen, beide aus). Quest-Items sind mit einem ! markiert. WoW: Forever kann von Classic abweichen, deshalb bleiben deine eigenen Zahlen getrennt. Eine Einstellung, standardmäßig an; nach diesem Update einmal das Spiel neu starten." } },
	{ id = 94, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: mouse drops hidden in combat", "The drops next to the mouse no longer show while you're in combat, and go away when a fight starts; when it ends with the mouse still over an enemy, they come back. A setting, on by default, right under the drops next to the mouse." },
		de = { "Bestiary: Maus-Drops im Kampf versteckt", "Die Drops neben der Maus erscheinen nicht mehr, während du im Kampf bist, und verschwinden, wenn ein Kampf beginnt; endet er, während die Maus noch über einem Gegner ist, kommen sie zurück. Eine Einstellung, standardmäßig an, direkt unter den Drops neben der Maus." } },
	{ id = 95, version = "0.6.0", module = "tweaks",
		en = { "Who has aggro, on enemy nameplates", "In a group, the left end of each enemy's health bar now says who it's attacking: >YOU< when it's you, else the first three letters of their name in the colour of their role: tank blue, healer green, damage red, white without a role. Small, outlined with a shadow, so the colour is what you see first. A mob casting at the healer while you tank it still says >YOU<. Roles come from the dungeon finder or a role check: in a group you made yourself, the leader can now start one (Misc Tweaks, or /lefthy tweaks rolecheck), and everyone picks in Blizzard's window. Try it (/lefthy tweaks aggrotest) shows examples on the enemy nameplates you see. Restart the game once after this update." },
		de = { "Wer Aggro hat, auf Namensplaketten", "In einer Gruppe zeigt das linke Ende des Lebensbalkens jedes Gegners jetzt, wen er angreift: >DU<, wenn du es bist, sonst die ersten drei Buchstaben des Namens in der Farbe der Rolle: Tank blau, Heiler grün, DD rot, weiß ohne Rolle. Klein, mit Umriss und Schatten, damit man zuerst die Farbe sieht. Ein Mob, der auf den Heiler zaubert, während du ihn tankst, zeigt weiter >DU<. Die Rollen kommen aus dem Dungeonbrowser oder einem Rollencheck: in einer selbst erstellten Gruppe kann der Anführer jetzt einen starten (Misc Tweaks, oder /lefthy tweaks rolecheck), und jeder wählt in Blizzards Fenster. Ausprobieren (/lefthy tweaks aggrotest) zeigt Beispiele auf den feindlichen Namensplaketten, die du siehst. Nach diesem Update einmal das Spiel neu starten." } },
	{ id = 96, version = "0.6.0", module = "general",
		en = { "The installer updates itself", "Update-LefthyTools.cmd now checks for a newer installer first: if there is one, it uses it and replaces itself with it, so your copy, and the one you pass on, never goes out of date. Copies from before this one can't do that yet: this is the last time you need a new file." },
		de = { "Der Installer aktualisiert sich", "Update-LefthyTools.cmd sucht jetzt zuerst nach einem neueren Installer: gibt es einen, nimmt es diesen und ersetzt sich selbst damit, sodass deine Kopie, und die, die du weitergibst, nie veraltet. Kopien von vorher können das noch nicht: dies ist das letzte Mal, dass du eine neue Datei brauchst." } },
	{ id = 97, version = "0.6.0", module = "beacon",
		en = { "Fight stream: the battle row", "Under a stream's map the row of mobs is now a little battle, Pokémon style: on the left the one you watch, on the right the mobs they fight. They cast their spells at their target or step up and strike it; the mob flinches and roughly what it lost floats up from it. Mobs lunge at them; their hits, heals, dodges and loot float up from their model, and the dead fall. It's an approximation from what the game tells addons. A friend near you in your group looks like themselves; one elsewhere is their class's emblem, with their portrait on top if they're in your group. Druids show the form they're in, weapons are sheathed while casting, skinning kneels, and a mob that dies falls at once. Restart the game once after this update." },
		de = { "Kampf-Stream: die Kampfreihe", "Unter der Karte eines Streams ist die Reihe der Mobs jetzt ein kleiner Kampf, im Pokémon-Stil: links der, den du zuschaust, rechts die Mobs, gegen die er kämpft. Er zaubert auf sein Ziel oder tritt vor und schlägt zu; der Mob zuckt zusammen, und ungefähr was er verloren hat, steigt von ihm auf. Mobs stürzen sich auf ihn; seine Treffer, Heilungen, Ausweichen und Loot steigen von seinem Modell auf, und die Toten fallen. Es ist eine Annäherung aus dem, was das Spiel Addons verrät. Ein Freund in deiner Nähe in deiner Gruppe sieht aus wie er selbst; einer woanders ist das Wappen seiner Klasse, in deiner Gruppe mit seinem Porträt obendrauf. Druiden zeigen ihre Gestalt, beim Zaubern ist die Waffe weggesteckt, beim Kürschnern wird gekniet, und ein Mob, der stirbt, fällt sofort. Nach diesem Update einmal das Spiel neu starten." } },
	{ id = 98, version = "0.6.0", module = "mirage",
		en = { "Mirage: pause for good", "Shift-click on Mirage's minimap button pauses fading for good: the interface stays visible, also after a restart, until you click the button again. Its pause sign turns orange, and chat reminds you after a login." },
		de = { "Mirage: dauerhaft pausieren", "Ein Shift-Klick auf Mirages Minimap-Button pausiert das Ausblenden dauerhaft: das Interface bleibt sichtbar, auch nach einem Neustart, bis du wieder auf den Button klickst. Das Pausenzeichen wird orange, und nach dem Einloggen erinnert dich der Chat daran." } },
	{ id = 99, version = "0.6.0", module = "beacon",
		en = { "Mob health from the classic database", "The fight stream knows a mob's health from the Bestiary's classic database, elites too, until two of your kills have measured it. Hovering a mob in the battle row says where its health comes from." },
		de = { "Mob-Leben aus der Classic-Datenbank", "Der Kampf-Stream kennt das Leben eines Mobs aus der Classic-Datenbank des Bestiary, auch bei Elites, bis zwei deiner Kills es gemessen haben. Der Tooltip eines Mobs in der Kampfreihe sagt, woher das Leben kommt." } },
	{ id = 100, version = "0.6.0", module = "beacon",
		en = { "Fight stream: who has aggro", "In a group, each mob in the battle row shows who has its aggro, like the nameplate tags: >YOU< or the first three letters of their name in their role's colour. Friends on an older LefthyTools don't send it (nothing breaks)." },
		de = { "Kampf-Stream: wer Aggro hat", "In einer Gruppe zeigt jeder Mob in der Kampfreihe, wer Aggro hat, wie auf den Namensplaketten: >DU< oder die ersten drei Buchstaben des Namens in der Farbe seiner Rolle. Freunde mit einem älteren LefthyTools schicken das nicht (es geht nichts kaputt)." } },
	{ id = 101, version = "0.6.0", module = "bestiary",
		en = { "Quest drops while questing", "While a quest wants an item a mob drops, the Bestiary window shows how far you are, its chance and about how many more kills. The drops beside the mouse get one small line for it." },
		de = { "Quest-Drops beim Questen", "Will eine Quest ein Item, das ein Mob droppt, zeigt das Bestiary-Fenster deinen Stand, die Chance und wie viele Kills es etwa noch braucht. Die Drops neben der Maus bekommen eine kleine Zeile dazu." } },
	{ id = 102, version = "0.6.0", module = "bestiary",
		en = { "Wish list and dry streak", "Alt-click a drop in the Bestiary to pin it: a star marks it wherever it shows, and the ledger lists your wishes. When it finally drops, one quiet line says after how many kills." },
		de = { "Wunschliste und Durststrecke", "Alt-Klick auf einen Drop im Bestiary merkt ihn vor: ein Stern markiert ihn überall, und das Verzeichnis zeigt deine Wünsche. Droppt er endlich, sagt eine ruhige Zeile, nach wie vielen Kills." } },
	{ id = 103, version = "0.6.0", module = "beacon",
		en = { "Fight stream: fight summaries", "When a fight ends, the stream window sums it up for a few seconds: how long it took, the kills, the XP and the lowest health, or that they died." },
		de = { "Kampf-Stream: Kampf-Zusammenfassung", "Nach einem Kampf fasst das Stream-Fenster ihn ein paar Sekunden zusammen: Dauer, Kills, EP und die niedrigsten HP, oder dass er gestorben ist." } },
	{ id = 104, version = "0.6.0", module = "beacon",
		en = { "Fight stream: rare finds", "Loot that's rare where it most likely came from (below 2%) floats up with its drop chance in gold, from the Bestiary's database or your own kills." },
		de = { "Kampf-Stream: seltene Funde", "Seltener Loot (unter 2 % beim wahrscheinlichsten Mob) steigt mit seiner Dropchance in Gold auf, aus der Datenbank des Bestiary oder deinen eigenen Kills." } },
	{ id = 105, version = "0.6.0", module = "beacon",
		en = { "Fight stream: Bestiary on hover", "Hovering a mob in the battle row shows your Bestiary card for it: your kills and its three likeliest drops." },
		de = { "Kampf-Stream: Bestiary per Mouseover", "Mouseover über einen Mob in der Kampfreihe zeigt deine Bestiary-Karte: deine Kills und seine drei wahrscheinlichsten Drops." } },
	{ id = 106, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: XP and time per kill", "Each of your kills now notes the XP it gave and how long it took. The window shows it in a small line under the portrait; the ledger adds the XP per hour of fighting and sorts by XP per kill or per hour, to compare leveling spots." },
		de = { "Bestiary: EP und Zeit pro Kill", "Jeder deiner Kills merkt sich jetzt die EP, die er gab, und wie lange er dauerte. Das Fenster zeigt es in einer kleinen Zeile unter dem Porträt; das Verzeichnis zeigt zusätzlich die EP pro Stunde Kampf und sortiert nach EP pro Kill oder pro Stunde, um Leveling-Spots zu vergleichen." } },
	{ id = 107, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: worth per kill", "A kill's worth is its coin plus what its drops sell for at a vendor. The Bestiary window shows it (worth ~45s), the ledger the details, and it can sort by it to show where farming pays." },
		de = { "Bestiary: Wert pro Kill", "Der Wert eines Kills ist sein Geld plus das, was seine Drops beim Händler bringen. Das Bestiary-Fenster zeigt ihn (Wert ~45s), das Verzeichnis die Details, und es kann danach sortieren, um zu zeigen, wo sich Farmen lohnt." } },
	{ id = 108, version = "0.6.0", module = "bestiary",
		en = { "Bestiary: where you killed them", "The Bestiary's ledger now shows, beside a mob's details, a map of the zone where you killed it most often (as far as you've explored it), with a dot for each of your last 50 kills; a dropdown picks its other zones." },
		de = { "Bestiary: wo du sie getötet hast", "Das Verzeichnis des Bestiary zeigt jetzt neben den Details eines Mobs eine Karte der Zone, in der du ihn am häufigsten getötet hast (so weit du sie erkundet hast), mit einem Punkt für jeden deiner letzten 50 Kills; ein Dropdown wählt die anderen Zonen." } },
	{ id = 109, version = "0.6.0", module = "beacon",
		en = { "Fight stream: spells in their colours", "In the battle row a spell glows in its school's colour as it flies, and its hit flashes in it: fire orange, frost blue, shadow purple and so on. Restart the game once after this update." },
		de = { "Kampf-Stream: Zauber in ihren Farben", "In der Kampfreihe leuchtet ein Zauber im Flug in der Farbe seiner Schule, und sein Treffer blitzt darin auf: Feuer orange, Frost blau, Schatten lila und so weiter. Nach diesem Update einmal das Spiel neu starten." } },
	{ id = 110, version = "0.6.0", module = "beacon",
		en = { "Fight stream: polymorphed mobs as sheep", "A mob they polymorph turns into a sheep in the battle row (or a pig, turtle or cow) until it takes damage, dies or the spell runs out." },
		de = { "Kampf-Stream: verwandelte Mobs als Schaf", "Verwandelt der Magier im Stream einen Mob, steht der in der Kampfreihe als Schaf da (oder Schwein, Schildkröte, Kuh), bis er Schaden nimmt, stirbt oder die Verwandlung ausläuft." } },
	{ id = 111, version = "0.6.0", module = "chronicle",
		en = { "One row per character", "Characters no longer show up twice (first name and full name). Each is shown once by the name the game shows, its BattleTag beside it; Compare and the leaderboards go by character. A character known only by its first name (from an older LefthyTools) has a grey ? until its surname is known: hover it to see when." },
		de = { "Eine Zeile pro Charakter", "Charaktere tauchen nicht mehr doppelt auf (Vorname und voller Name). Jeder steht einmal da, mit dem Namen, den das Spiel zeigt, und seinem BattleTag daneben; Vergleich und Bestenlisten gehen nach Charakter. Ein Charakter, von dem nur der Vorname bekannt ist (von einem älteren LefthyTools), hat ein graues ?, bis sein Nachname bekannt ist: fahr mit der Maus darüber, um zu sehen, wann." } },
	{ id = 112, version = "0.6.0", module = "chronicle",
		en = { "Full names from friends' journals", "Your friends' characters show their full names, also those that weren't online with you. Their LefthyTools needs this update." },
		de = { "Volle Namen aus Tagebüchern", "Die Charaktere deiner Freunde zeigen ihren vollen Namen, auch die, die nicht mit dir online waren. Ihr LefthyTools braucht dieses Update." } },
	{ id = 113, version = "0.6.0", module = "chronicle",
		en = { "A death counts once", "The game sometimes reports one death several times. Chronicle now counts it once, and deaths saved twice before show once." },
		de = { "Ein Tod zählt einmal", "Das Spiel meldet einen Tod manchmal mehrfach. Chronicle zählt ihn jetzt einmal, und doppelt gespeicherte Tode erscheinen nur einmal." } },
	{ id = 114, version = "0.6.0", module = "chronicle",
		en = { "Leaderboard follows 7/14/30 days", "The leaderboard on Chronicle's Compare page ranks the range you pick, like the charts." },
		de = { "Bestenliste folgt 7/14/30 Tagen", "Die Bestenliste auf Chronicles Vergleich-Seite wertet den gewählten Zeitraum aus, wie die Grafiken." } },
	{ id = 115, version = "0.6.0", module = "chronicle",
		en = { "Surnames from Battle.net", "Chronicle learns a character's full name as soon as your friend is online on it, even with an older LefthyTools or none, and passes it on to your other friends." },
		de = { "Nachnamen von Battle.net", "Chronicle lernt den vollen Namen eines Charakters, sobald dein Freund damit online ist, auch mit älterem oder ohne LefthyTools, und gibt ihn an deine anderen Freunde weiter." } },
	{ id = 116, version = "0.6.0", module = "beacon",
		en = { "Mailing a won item: the right name", "Attaching it to a mail fills in the winner's character name, without the surname the mail wouldn't take." },
		de = { "Post an Gewinner: der richtige Name", "Beim Anhängen an eine Post steht der Charaktername des Gewinners drin, ohne den Nachnamen, den die Post nicht annimmt." } },
	{ id = 117, version = "0.6.0", module = "beacon",
		en = { "Your own lines show your full name", "Your map ping, announcements, LTC lines and the level-up preview name you the way your friends see you." },
		de = { "Deine Zeilen mit vollem Namen", "Dein Karten-Ping, Ankündigungen, LTC-Zeilen und die Level-Up-Vorschau zeigen dich so, wie deine Freunde dich sehen." } },
	{ id = 118, version = "0.6.0", module = "tweaks",
		en = { "Flights: no old destination", "A flight not taken from the flight map no longer gets the name and time of an earlier pick that never took off." },
		de = { "Flüge: kein altes Ziel mehr", "Ein Flug, der nicht über die Flugkarte gestartet wurde, bekommt nicht mehr Namen und Zeit einer früheren Auswahl, die nie abgeflogen ist." } },
	{ id = 119, version = "0.6.0", module = "chronicle",
		en = { "Journal syncs again after a clock error", "If your PC's clock was once more than a week ahead, friends stopped getting your news; Chronicle now fixes that by itself." },
		de = { "Tagebuch nach Uhrfehler wieder synchron", "War die Uhr deines PCs einmal über eine Woche vorgestellt, bekamen Freunde nichts Neues mehr von dir; Chronicle behebt das jetzt selbst." } },
	{ id = 120, version = "0.6.0", module = "mirage",
		en = { "/mirage understands 1,5", "Numbers after /mirage can have a decimal comma, the way the German client shows them." },
		de = { "/mirage versteht 1,5", "Zahlen nach /mirage dürfen ein Dezimalkomma haben, so wie der deutsche Client sie anzeigt." } },
	{ id = 121, version = "0.6.0", module = "general",
		en = { "Updater: restart for new saved data", "The updater also asks you to restart the game when an update adds saved data, not just files." },
		de = { "Updater: Neustart bei neuen Daten", "Der Updater sagt jetzt auch einen Neustart an, wenn ein Update neue gespeicherte Daten bringt, nicht nur neue Dateien." } },
	{ id = 122, version = "0.6.0", module = "general",
		en = { "Restart once after this update", "Several parts of LefthyTools are now in more, smaller files (easier to work on, nothing changes for you): restart the game once, a /reload isn't enough." },
		de = { "Nach diesem Update einmal neu starten", "Mehrere Teile von LefthyTools stecken jetzt in mehr, kleineren Dateien (leichter zu pflegen, für dich ändert sich nichts): starte das Spiel einmal neu, ein /reload reicht nicht." } },
	{ id = 123, version = "0.6.0", module = "beacon",
		en = { "Item rolls: your win says so again", "With a surname, your own win showed your name instead of telling you that you won." },
		de = { "Würfeln: dein Gewinn wieder erkannt", "Mit Nachnamen zeigte dein eigener Gewinn deinen Namen, statt dir zu sagen, dass du gewonnen hast." } },
	{ id = 124, version = "0.6.0", module = "chronicle",
		en = { "News keeps bosses through quest days", "Chronicle's News keeps a share for each kind of news, so a day full of quests no longer pushes out a friend's boss kill, and up to 30 characters per friend are kept, the ones played most recently." },
		de = { "Neues behält Bosse trotz Quest-Tagen", "Chronicles Tab Neues hält für jede Art von Ereignis einen eigenen Anteil, damit ein Tag voller Quests den Boss-Kill eines Freundes nicht mehr verdrängt, und pro Freund bleiben bis zu 30 Charaktere, die zuletzt gespielten." } },
	{ id = 125, version = "0.6.0", module = "chronicle",
		en = { "Less traffic between friends", "After a /reload, friends with an up-to-date LefthyTools no longer get a week of your numbers again: they come with your journal." },
		de = { "Weniger Datenverkehr unter Freunden", "Nach einem /reload bekommen Freunde mit aktuellem LefthyTools nicht mehr erneut eine Woche deiner Zahlen: die kommen mit deinem Tagebuch." } },
	{ id = 126, version = "0.6.0", module = "chronicle",
		en = { "Days as T in German", "On German clients Chronicle writes days in durations as T (4T 4h) instead of d." },
		de = { "Tage in Zeitangaben als T", "Chronicle schreibt Tage in Zeitangaben jetzt als T (4T 4h) statt d." } },
	{ id = 127, version = "0.6.0", module = "chronicle",
		en = { "Friends tab tooltips fixed", "A friend with many characters no longer makes the tooltip very wide (long lines wrap, characters one per line), and a tooltip stays open while the tab refreshes every few seconds." },
		de = { "Tooltips im Freunde-Tab repariert", "Ein Freund mit vielen Charakteren macht den Tooltip nicht mehr riesig breit (lange Zeilen brechen um, Charaktere stehen untereinander), und ein Tooltip bleibt offen, während sich der Tab alle paar Sekunden aktualisiert." } },
	{ id = 128, version = "0.6.0", module = "general",
		en = { "Installer: no wait for network drives", "The installer goes straight to your game folder from last time and no longer hangs on disconnected network drives or drives that are gone." },
		de = { "Installer: kein Warten auf Netzlaufwerke", "Der Installer nimmt direkt deinen Spielordner vom letzten Mal und hängt nicht mehr an getrennten Netzlaufwerken oder Laufwerken, die es nicht mehr gibt." } },
	{ id = 129, version = "0.7.0", module = "general",
		en = { "Installer knows the release", "The installer recognises WoW: Forever's release folder and, while the beta is still installed too, updates both at once." },
		de = { "Installer kennt den Release", "Der Installer erkennt den Release-Ordner von WoW: Forever und aktualisiert, solange die Beta auch noch installiert ist, beide auf einmal." } },
	{ id = 130, version = "0.7.0", module = "general",
		en = { "The release starts fresh", "On WoW: Forever's release, LefthyTools ignores saved data copied over from the beta (settings, journal, Bestiary) and starts fresh once, with a chat line." },
		de = { "Das Release startet frisch", "Auf dem Release von WoW: Forever nutzt LefthyTools keine aus der Beta kopierten Daten (Einstellungen, Tagebuch, Bestiary), sondern startet einmal frisch, mit einer Chatzeile." } },
	{ id = 131, version = "0.7.0", module = "tweaks",
		en = { "Spells and quests of the release", "The level-up window's trainer spells and the markers for quests new in Forever come from the release build: 12 spells and 7 quests more." },
		de = { "Zauber und Quests vom Release", "Die Trainer-Zauber im Level-Up-Fenster und die Markierungen für Quests, die neu in Forever sind, stammen vom Release-Build: 12 Zauber und 7 Quests mehr." } },
	{ id = 132, version = "0.7.0", module = "echoes",
		en = { "Echoes records your journey", "New module: Echoes records where you go and what happens on the way (level-ups, quests, kills, loot, deaths, dungeons) for a replay of the whole group on a map website. It only records, nothing shows in game; your recordings travel to the friend who collects them. /lefthy echoes shows what's recorded, and you can switch Echoes off in the settings." },
		de = { "Echoes zeichnet deine Reise auf", "Neues Modul: Echoes zeichnet auf, wo du hinläufst und was dabei passiert (Level-ups, Quests, Kills, Loot, Tode, Dungeons), für ein Replay der ganzen Gruppe auf einer Karten-Webseite. Es zeichnet nur auf, im Spiel zeigt es nichts; deine Aufzeichnungen wandern zu dem Freund, der sie sammelt. /lefthy echoes zeigt, was aufgezeichnet ist, und in den Einstellungen kannst du Echoes abschalten." } },
	{ id = 133, version = "0.7.0", module = "general",
		en = { "Restart once after this update", "Echoes brings new files and new saved data: restart the game once, a /reload isn't enough." },
		de = { "Nach diesem Update einmal neu starten", "Echoes bringt neue Dateien und neue gespeicherte Daten mit: starte das Spiel einmal neu, ein /reload reicht nicht." } },
	{ id = 134, version = "0.7.0", module = "beacon",
		en = { "A quick second hello is answered", "When a friend's LefthyTools says hello again within seconds (a quick /reload), Beacon answers a moment later instead of ignoring it, so the two of you find each other right away." },
		de = { "Schnelles zweites Hallo beantwortet", "Sagt das LefthyTools eines Freundes innerhalb von Sekunden erneut Hallo (ein schnelles /reload), antwortet Beacon kurz darauf, statt es zu ignorieren, damit ihr euch sofort wiederfindet." } },
	{ id = 135, version = "0.7.0", module = "chronicle",
		en = { "New rare drops are noticed", "A rare or epic drop of an item your game had never seen before was missed by Chronicle's highlights and the fight stream's rare finds; its quality now comes from the item link." },
		de = { "Neue seltene Drops werden erkannt", "Ein seltener oder epischer Drop eines Items, das dein Spiel noch nie gesehen hatte, fehlte in Chronicles Highlights und bei den seltenen Funden im Kampf-Stream; seine Qualität kommt jetzt aus dem Item-Link." } },
	{ id = 136, version = "0.7.0", module = "echoes",
		en = { "Echoes stays out of the way", "Echoes does its work in small steps: nothing heavy in a fight, at login or when many friends are online, and it sends less when nothing changed." },
		de = { "Echoes bleibt im Hintergrund", "Echoes arbeitet in kleinen Schritten: nichts Schweres im Kampf, beim Einloggen oder wenn viele Freunde online sind, und es sendet weniger, wenn sich nichts geändert hat." } },
	{ id = 137, version = "0.7.0", module = "chronicle",
		en = { "Journals wait out fights", "Friends' journals and days are no longer sent, built or merged during a fight, but right after it, in small steps; the minimap dot for news no longer costs a hitch." },
		de = { "Tagebücher warten Kämpfe ab", "Tagebücher und Tage von Freunden werden während eines Kampfes nicht mehr gesendet, erstellt oder eingearbeitet, sondern direkt danach, in kleinen Schritten; der Minimap-Punkt für Neues kostet keinen Ruckler mehr." } },
	{ id = 138, version = "0.7.0", module = "tweaks",
		en = { "Spells of the launch build", "The level-up window's trainer spells, flight times and the quest markers come from the launch build: spells Forever took away from the trainers no longer show, its new ones do." },
		de = { "Zauber vom Launch-Build", "Die Trainer-Zauber im Level-Up-Fenster, die Flugzeiten und die Quest-Markierungen stammen vom Launch-Build: Zauber, die Forever bei den Trainern entfernt hat, fehlen jetzt, seine neuen sind dabei." } },
	{ id = 139, module = "beacon",
		en = { "Friends' levels", "Battle.net gives friends' levels as 0 on the release, so Chronicle and the friend tooltips showed level 0. Friends now tell you their level themselves; until they've updated it comes from their journal, level-ups or your group, else it shows a dash." },
		de = { "Level von Freunden", "Battle.net meldet auf dem Release für Freunde Level 0, darum zeigten Chronicle und die Tooltips Level 0. Freunde teilen dir ihr Level jetzt selbst mit; bis sie aktualisiert haben, kommt es aus ihrem Tagebuch, ihren Level-ups oder deiner Gruppe, sonst steht dort ein Strich." } },
	{ id = 140, module = "beacon",
		en = { "Mail to the winner works", "When you attach an item someone won, the mail now fills in their name and surname. The server name it added before made the mail impossible to send." },
		de = { "Post an den Gewinner funktioniert", "Hängst du ein gewonnenes Item an eine Post, trägt sie jetzt Name und Nachname des Gewinners ein. Mit dem bisher angehängten Servernamen ließ sich die Post nicht senden." } },
	{ id = 141, module = "beacon",
		en = { "The stream's map on Zephras Isle", "The fight stream's map now shows the terrain on Zephras Isle too, as it does on the continents." },
		de = { "Die Stream-Karte auf Zephras Isle", "Die Karte im Kampf-Stream zeigt jetzt auch auf Zephras Isle das Gelände, wie auf den Kontinenten." } },
	{ id = 142, module = "beacon",
		en = { "Invite friends from the map", "Shift+left click a friend's dot on the world map to invite them to your group." },
		de = { "Freunde von der Karte einladen", "Shift+Linksklick auf den Punkt eines Freundes auf der Weltkarte lädt ihn in deine Gruppe ein." } },
	{ id = 143, module = "beacon",
		en = { "Friends' real levels", "Friends now always show the level their character really has. Battle.net's number can be wrong, and it's only used for friends who haven't updated yet. Everyone needs this version for it." },
		de = { "Die echten Level deiner Freunde", "Freunde zeigen jetzt immer das Level, das ihr Charakter wirklich hat. Die Zahl von Battle.net kann falsch sein und wird nur noch für Freunde genutzt, die noch nicht aktualisiert haben. Dafür brauchen alle diese Version." } },
	{ id = 144, module = "beacon",
		en = { "Health moves in the fight stream again", "The game now hides how much a hit takes, so friends' streams showed full health until the end. Your health and the mobs' are now estimated from the hits themselves and set right after each fight from the damage meter (it can stay switched off). They are rough at first and get better as you fight. Hits no longer show numbers; dodges and misses are back. Whoever is fighting needs this version." },
		de = { "Leben im Kampf-Stream bewegt sich wieder", "Das Spiel verbirgt jetzt, wie viel ein Treffer abzieht, darum zeigten Streams von Freunden bis zum Ende volles Leben. Dein Leben und das der Mobs werden jetzt aus den Treffern selbst geschätzt und nach jedem Kampf mit dem Damage Meter korrigiert (es kann ausgeschaltet bleiben). Am Anfang ist das grob und wird mit jedem Kampf besser. Treffer zeigen keine Zahlen mehr, Ausweichen und Verfehlen sind zurück. Wer kämpft, braucht diese Version." } },
	{ id = 145, module = "chronicle",
		en = { "Everyone's recipes in Chronicle", "A new Professions tab shows your friends' professions and known recipes, also while they're offline, with the item, its reagents against your bags, and a search for who can craft what." },
		de = { "Alle Rezepte in Chronicle", "Der neue Tab Berufe zeigt die Berufe und bekannten Rezepte deiner Freunde, auch wenn sie offline sind, mit dem Item, den Reagenzien im Vergleich zu deinen Taschen und einer Suche, wer was herstellen kann." } },
	{ id = 146, module = "chronicle",
		en = { "Recipes against your gear", "In the Professions tab, gear shows what it would change against what you wear, and a recipe you know opens in your profession window with a click." },
		de = { "Rezepte im Vergleich zur Ausrüstung", "Im Tab Berufe zeigt Ausrüstung, was sie gegenüber deiner aktuellen ändern würde, und ein Rezept, das du kennst, öffnest du per Klick in deinem Berufsfenster." } },
	{ id = 147, module = "beacon",
		en = { "LTC in its own chat tab", "Tick LTC in a chat tab's settings to show it there. A tab out of sight flashes on new lines, and LTC's colour is now a setting." },
		de = { "LTC in einem eigenen Chat-Tab", "Kreuze LTC in den Einstellungen eines Chat-Tabs an, um es dort anzuzeigen. Ein verdeckter Tab blinkt bei neuen Zeilen, und die Farbe von LTC lässt sich einstellen." } },
	{ id = 148, module = "chronicle",
		en = { "Find people in the Professions tab", "The search in the Professions tab also finds a character or BattleTag name, and lights up their professions." },
		de = { "Personen im Tab Berufe finden", "Die Suche im Tab Berufe findet auch Charakter- und BattleTag-Namen und hebt deren Berufe hervor." } },
	{ id = 149, module = "beacon",
		en = { "A choice of sounds for LTC", "Beacon's settings now let you choose the sound a friend's LTC line plays." },
		de = { "Töne für LTC zur Auswahl", "In den Beacon-Einstellungen wählst du jetzt den Ton für die LTC-Zeilen deiner Freunde." } },
	{ id = 150, module = "tweaks",
		en = { "Xbox or PlayStation symbols", "A new setting in Misc Tweaks chooses which symbols the game shows for your controller's buttons." },
		de = { "Xbox- oder PlayStation-Symbole", "Eine neue Einstellung in Misc Tweaks wählt, welche Symbole das Spiel für die Tasten deines Controllers zeigt." } },
	{ id = 151, module = "general",
		en = { "A settings window of its own", "LefthyTools' settings moved out of Blizzard's Options into their own window, with a search and real dropdowns. Your settings stay as they were. Open it with /lefthy." },
		de = { "Ein eigenes Einstellungsfenster", "Die Einstellungen von LefthyTools sind aus Blizzards Optionen in ein eigenes Fenster gezogen, mit Suche und echten Auswahllisten. Deine Einstellungen bleiben, wie sie waren. Du öffnest es mit /lefthy." } },
	{ id = 152, module = "tweaks",
		en = { "Quest lines wait out the fight", "Quest progress in party chat is now sent once the fight is over." },
		de = { "Quest-Zeilen warten den Kampf ab", "Questfortschritt im Gruppenchat wird jetzt gesendet, sobald der Kampf vorbei ist." } },
	{ id = 153, module = "tweaks",
		en = { "Combo dots: no blocked action", "A new target in a fight: the combo point dots come onto its nameplate once the game allows it, instead of an error about a blocked action." },
		de = { "Combopunkte: keine blockierte Aktion", "Neues Ziel im Kampf: Die Combopunkte kommen an seine Namensplakette, sobald das Spiel es erlaubt, statt eines Fehlers über eine blockierte Aktion." } },
	{ id = 154, module = "chronicle",
		en = { "Who can craft it, in tooltips", "An item's tooltip names who of you and your friends can craft it, best skill first. Hold Shift for the reagents. A setting in Chronicle switches it off." },
		de = { "Wer es herstellen kann, im Tooltip", "Der Tooltip eines Items nennt, wer von dir und deinen Freunden es herstellen kann, der höchste Skill zuerst. Halte Shift für die Reagenzien. Eine Einstellung in Chronicle schaltet es ab." } },
	{ id = 155, module = "beacon",
		en = { "Told when your error is already fixed", "Report an error that a newer build already fixed, and you get one chat line from the friend who collects reports: update with Update-LefthyTools.cmd and restart the game." },
		de = { "Hinweis, wenn dein Fehler behoben ist", "Meldest du einen Fehler, den ein neuerer Build schon behoben hat, bekommst du vom Freund, der die Berichte sammelt, eine Chatzeile: Update mit Update-LefthyTools.cmd und starte das Spiel neu." } },
	{ id = 156, module = "general",
		en = { "Changed settings stand out", "In the settings window, a setting you changed has a gold dot and a button back to its default; each page can be reset at its foot. Settings added by an update say \"New\" until you've opened their page." },
		de = { "Geänderte Einstellungen fallen auf", "Im Einstellungsfenster hat eine geänderte Einstellung einen goldenen Punkt und einen Button zurück auf Standard; jede Seite lässt sich unten zurücksetzen. Neue Einstellungen aus einem Update zeigen \"Neu\", bis du ihre Seite geöffnet hast." } },
	{ id = 157, module = "beacon",
		en = { "LTC: missed lines, mentions, who's in", "Friends who were offline get the LTC lines of the last 24 hours when they come online, with their time. A line with your name stands out and flashes. /ltc who <text> asks who's in: friends click I'm in or Not now, and Invite all invites them. Everyone needs this version for it." },
		de = { "LTC: Verpasstes, Erwähnungen, Wer dabei", "Freunde, die offline waren, bekommen beim Einloggen die LTC-Zeilen der letzten 24 Stunden, mit Uhrzeit. Eine Zeile mit deinem Namen fällt auf und blinkt. /ltc who <Text> fragt, wer dabei ist: Freunde klicken Bin dabei oder Grad nicht, und Alle einladen lädt sie ein. Dafür brauchen alle diese Version." } },
	{ id = 158, module = "chronicle",
		en = { "Crafting margins at the AH", "A Margins button on your profession window shows what a recipe costs and brings, and gold per hour, from the auction house's and vendors' prices. At the auction house it checks them, or scans all your recipes; the list shows the best first." },
		de = { "Handwerks-Margen am AH", "Ein Margen-Button an deinem Berufsfenster zeigt, was ein Rezept kostet und einbringt, und Gold pro Stunde, aus den Preisen von AH und Händlern. Am AH prüft er sie oder scannt alle deine Rezepte; die Liste zeigt die besten zuerst." } },
	{ id = 159, module = "tweaks",
		en = { "Sorted bags with a controller", "In gamepad mode the bags show the bag buttons in a row at the top and your items in sections: gear, consumables, trade goods, quest items, other and junk, sorted by quality and name. The selected item's tooltip sits beside the bags. A slider sets how many columns wide they are." },
		de = { "Sortierte Taschen mit Controller", "Im Gamepad-Modus zeigen die Taschen oben die Taschen-Buttons in einer Reihe und deine Items in Abschnitten: Ausrüstung, Verbrauchsgüter, Handwerkswaren, Questgegenstände, Sonstiges und Plunder, nach Qualität und Name sortiert. Der Tooltip des gewählten Items steht neben den Taschen. Ein Regler legt fest, wie viele Spalten breit sie sind." } },
	{ id = 160, module = "beacon",
		en = { "Fight stream: no blocked action", "Sharing your fights no longer causes an error about a blocked action a few seconds into a fight: distances to enemies come from spell ranges only while you fight." },
		de = { "Kampf-Stream: keine blockierte Aktion", "Das Teilen deiner Kämpfe verursacht keinen Fehler über eine blockierte Aktion mehr kurz nach Kampfbeginn: Entfernungen zu Gegnern kommen im Kampf nur noch aus Zauberreichweiten." } },
	{ id = 161, module = "tweaks",
		en = { "Controller bags: tidier", "The sorted controller bags fold the bag buttons' row away under a \"Bags\" header (the controller's cursor on it opens it) and show one free slot that says how many are free. A setting brings back every free slot." },
		de = { "Controller-Taschen: aufgeräumter", "Die sortierten Controller-Taschen klappen die Reihe der Taschen-Buttons unter einer Überschrift „Taschen“ ein (der Controller-Cursor darauf klappt sie auf) und zeigen einen freien Platz, der sagt, wie viele frei sind. Eine Einstellung holt jeden freien Platz zurück." } },
	{ id = 162, module = "tweaks",
		en = { "Sorted bags with mouse and keyboard", "The sorted bags (sections, one free slot with the count, the columns slider) now come with mouse and keyboard too, the reagent bag's items in them instead of a window of its own. Misc Tweaks switches them off for Blizzard's own bag." },
		de = { "Sortierte Taschen mit Maus und Tastatur", "Die sortierten Taschen (Abschnitte, ein freier Platz mit der Anzahl, der Spalten-Regler) gibt es jetzt auch mit Maus und Tastatur, mit den Items der Reagenzientasche statt eines eigenen Fensters. Misc Tweaks schaltet sie für Blizzards eigene Tasche aus." } },
	{ id = 163, module = "beacon",
		en = { "Fight stream: really no blocked action", "Spell range checks on enemies are blocked in a fight too, so sharing your fights no longer asks any: an enemy's distance is unknown while you fight." },
		de = { "Kampf-Stream: wirklich keine Blockade", "Auch Zauberreichweiten zu Gegnern werden im Kampf blockiert, deshalb fragt das Teilen deiner Kämpfe keine mehr ab: Die Entfernung eines Gegners ist im Kampf unbekannt." } },
	{ id = 164, module = "beacon",
		en = { "Fight stream: distances in fights again", "Enemies in a shared fight have their distance again. The blocked action came from range checks on friendly players, which the game refuses in a fight; those are skipped now." },
		de = { "Kampf-Stream: Entfernungen im Kampf", "Gegner in einem geteilten Kampf haben wieder ihre Entfernung. Die blockierte Aktion kam von Reichweiten-Abfragen zu freundlichen Spielern, die das Spiel im Kampf verweigert; die fallen jetzt weg." } },
	{ id = 165, module = "tweaks",
		en = { "Quest lines right away again", "Quest progress in party chat goes out at once again, in fights too. Only the game's own chat lockdown (boss encounters, challenge modes, PvP) holds it back." },
		de = { "Quest-Zeilen wieder sofort", "Questfortschritt im Gruppenchat geht wieder sofort raus, auch im Kampf. Nur die Chat-Sperre des Spiels (Bossbegegnungen, Herausforderungen, PvP) hält ihn zurück." } },
	{ id = 166, module = "tweaks",
		en = { "Movable loot rolls", "Drag the loot roll window (Need / Greed), with the controller too, and it comes up there from then on. /lefthy tweaks resetloot puts it back." },
		de = { "Verschiebbare Würfelfenster", "Zieh das Würfelfenster (Bedarf/Gier), auch mit Controller, und es erscheint von da an dort. /lefthy tweaks resetloot setzt es zurück." } },
	{ id = 167, module = "chronicle",
		en = { "Chronicle: hover loot for its tooltip", "Loot in Chronicle's timeline and news can be hovered for the item's tooltip and clicked like a chat link (Shift-click puts it in the chat box)." },
		de = { "Chronicle: Tooltip für Beute", "Beute in Chronicles Zeitleiste und Neuigkeiten zeigt beim Drüberfahren den Tooltip des Items und lässt sich wie ein Chat-Link anklicken (Shift-Klick setzt ihn in den Chat)." } },
	{ id = 168, module = "general",
		en = { "Map: no blocked controller actions", "Friends' dots, pings and quests on the world map are LefthyTools' own frames now, so closing the map with the controller no longer gets the game's actions blocked (interact icons, B, targeting). The controller's map cursor shows their tooltips." },
		de = { "Karte: keine Blockaden mit Controller", "Freunde, Pings und Quests auf der Weltkarte sind jetzt eigene Frames von LefthyTools, deshalb blockiert das Schließen der Karte mit dem Controller keine Aktionen des Spiels mehr (Interaktions-Icons, B, Ziele). Der Karten-Cursor des Controllers zeigt ihre Tooltips." } },
	{ id = 169, module = "lodestar",
		en = { "Lodestar: every zone's quest chains", "A new module. /lodestar browse (or the star on the minimap) opens the quest browser: a zone's map, uncovered, with every quest giver for your level, and beside it what to turn in, what's in progress and the zone's chains. Pick a quest for its steps, objectives on the map, turn-in and rewards; Chain above the map shows its whole chain and the way to a locked quest. My quests sorts your log, the level path says where to go next." },
		de = { "Lodestar: Questreihen jeder Zone", "Ein neues Modul. /lodestar browse (oder der Stern an der Minimap) öffnet den Quest-Browser: die Karte einer Zone, ganz aufgedeckt, mit jedem Questgeber für dein Level, daneben was du abgeben kannst, was läuft und die Questreihen der Zone. Wähle eine Quest für ihre Schritte, Ziele auf der Karte, Abgabe und Belohnungen; Questreihe über der Karte zeigt die ganze Reihe und den Weg zu einer gesperrten Quest. Meine Quests sortiert dein Questlog, der Levelpfad sagt, wohin als Nächstes." } },
	{ id = 170, module = "lodestar",
		en = { "Lodestar: a quest companion", "/lodestar (or right-click the star on the minimap) opens a small window that follows what you do: the quest you're on with its step in its chain, its objectives and where they are on its map, where to turn it in, and what to pick up next nearby, nearest first." },
		de = { "Lodestar: ein Quest-Begleiter", "/lodestar (oder Rechtsklick auf den Stern an der Minimap) öffnet ein kleines Fenster, das mitgeht: die Quest, an der du bist, mit ihrem Schritt in der Questreihe, ihren Zielen und wo sie auf seiner Karte liegen, wo du sie abgibst, und was du als Nächstes in der Nähe annehmen kannst, das Nächste zuerst." } },
	{ id = 171, module = "lodestar",
		en = { "Lodestar in the quest window and log", "Beside a quest's dialog Lodestar shows its level and XP before you accept it, and in a chain which part it is and what it leads to. Your quest log shows each chain quest's step (2/4); Alt-click opens a quest in Lodestar. Quest givers' tooltips say what they start and take back." },
		de = { "Lodestar im Questfenster und -log", "Neben dem Questfenster zeigt Lodestar Level und EP einer Quest, bevor du sie annimmst, und in einer Questreihe, der wievielte Teil sie ist und wozu sie führt. Dein Questlog zeigt bei Quests einer Questreihe ihren Schritt (2/4); Alt-Klick öffnet eine Quest in Lodestar. Tooltips von Questgebern sagen, was sie vergeben und annehmen." } },
	{ id = 172, module = "lodestar",
		en = { "Lodestar: quest items in tooltips", "A quest item's tooltip says which quest it's for and where that stands: in your log with your progress, not taken yet or done. When no quest needs it any more it says you can discard it, and the sorted bags mark it with a small red x." },
		de = { "Lodestar: Questgegenstände im Tooltip", "Der Tooltip eines Questgegenstands sagt, für welche Quest er ist und wie es um sie steht: im Questlog mit deinem Fortschritt, noch nicht angenommen oder erledigt. Braucht ihn keine Quest mehr, sagt er, dass du ihn wegwerfen kannst, und die sortierten Taschen markieren ihn mit einem kleinen roten x." } },
	{ id = 173, module = "lodestar",
		en = { "Lodestar learns, friends share", "While you quest, Lodestar notes who gives and takes back the quests its data doesn't know, and what comes before them. Friends with LefthyTools pass it on, and see how far each of you got on a quest." },
		de = { "Lodestar lernt, Freunde teilen", "Beim Questen merkt sich Lodestar, wer Quests vergibt und annimmt, die seine Daten nicht kennen, und was vor ihnen kommt. Freunde mit LefthyTools geben das weiter und sehen, wie weit ihr jeweils bei einer Quest seid." } },
	{ id = 174, module = "lodestar",
		en = { "Lodestar: only quests you can take", "The level path and the zones' \"7 for your level\" count only quests you can take now or have in your log: none of the other faction, none that need another quest first, no holiday quests outside their event. All levels still shows holiday quests." },
		de = { "Lodestar: nur annehmbare Quests", "Der Levelpfad und das \"7 für dein Level\" der Zonen zählen nur Quests, die du jetzt annehmen kannst oder im Questlog hast: keine der anderen Fraktion, keine, die erst eine andere Quest brauchen, keine Feiertagsquests außerhalb ihres Events. Alle Level zeigt Feiertagsquests weiterhin." } },
	{ id = 175, module = "lodestar",
		en = { "Lodestar: difficulty and order", "Quests are coloured by how hard they are for you, counting the mobs you fight, group quests a step harder: \"for your level\" counts green and yellow ones, orange ones are counted as hard. Every list has one order: ready to turn in, in your log, for your level, hard, then by level. Click a quest to see it on the map, right-click for its chain; the quest browser has a button for your current zone and lists zones alphabetically." },
		de = { "Lodestar: Schwierigkeit und Ordnung", "Quests haben die Farbe ihrer Schwierigkeit für dich, mit den Mobs, die du bekämpfst, Gruppenquests eine Stufe schwerer: \"für dein Level\" zählt grüne und gelbe, orange zählen als schwer. Jede Liste hat dieselbe Ordnung: abgabebereit, im Questlog, für dein Level, schwer, dann nach Level. Klick auf eine Quest zeigt sie auf der Karte, Rechtsklick ihre Questreihe; der Quest-Browser hat einen Button für deine aktuelle Zone und listet die Zonen alphabetisch." } },
	{ id = 176, module = "beacon",
		en = { "Beacon: given away, no longer reserved", "A won item traded or mailed to someone other than its winner is no longer reserved for them: its \"Won by\" line and border go, also from the other copies of the same item (crafted items are all alike). Trades and mails to the winner are also noticed when the game empties the slots early." },
		de = { "Beacon: weitergegeben, nicht reserviert", "Ein gewonnenes Item, das du jemand anderem als dem Gewinner handelst oder schickst, ist nicht mehr für ihn reserviert: Die Zeile \"Gewonnen von\" und der Rahmen verschwinden, auch bei anderen Exemplaren desselben Items (hergestellte Items sind alle gleich). Handel und Post an den Gewinner werden auch erkannt, wenn das Spiel die Plätze früh leert." } },
	{ id = 177, module = "lodestar",
		en = { "Lodestar: quest items with levels", "A quest item's tooltip says the level of a quest you haven't taken yet, and leaves out quests that are grey for you (an item only they need says you can discard it). Lodestar's settings can show them again." },
		de = { "Lodestar: Questgegenstände mit Level", "Der Tooltip eines Questgegenstands nennt das Level einer Quest, die du noch nicht angenommen hast, und lässt Quests weg, die für dich grau sind (bei einem Item, das nur sie brauchen, steht, dass du es wegwerfen kannst). In Lodestars Einstellungen lassen sie sich wieder einblenden." } },
	{ id = 178, module = "lodestar",
		en = { "Lodestar: plan your quests", "The + beside a quest puts it on your plan. The new Plan tab lists your quests in your order: drag them around, or let Lodestar suggest a shorter route through their stops. The companion shows the next stop on top, with its own map and Skip. In My quests a click shows a quest's details, Ctrl-click shows it on the map. Alt-click on a quest in any list adds it to the plan or takes it off." },
		de = { "Lodestar: Quests planen", "Das + neben einer Quest setzt sie auf deinen Plan. Der neue Reiter Plan listet deine Quests in deiner Reihenfolge: Zieh sie herum, oder lass Lodestar eine kürzere Route durch ihre Stationen vorschlagen. Der Begleiter zeigt oben die nächste Station, mit eigener Karte und Überspringen. In Meine Quests zeigt ein Klick die Details einer Quest, Strg-Klick zeigt sie auf der Karte. Alt-Klick auf eine Quest in einer Liste setzt sie auf den Plan oder nimmt sie herunter." } },
	{ id = 179, module = "lodestar",
		en = { "Lodestar: find it on the map", "Clicking a quest in a list shows its details with the small map first; Ctrl-click or \"Show on map\" opens the big map, where its pins and areas come into view and pulse. A giver, turn-in or objective clicked in the details zooms to that spot. A + beside each quest puts it in your plan, whose stops show numbered on the map." },
		de = { "Lodestar: auf der Karte finden", "Ein Klick auf eine Quest in einer Liste zeigt zuerst ihre Details mit der kleinen Karte; Strg-Klick oder \"Auf der Karte zeigen\" öffnet die große Karte, wo ihre Punkte und Gebiete ins Bild kommen und pulsieren. Ein Klick auf Questgeber, Abgabe oder Ziel in den Details zoomt zu dieser Stelle. Ein + neben jeder Quest setzt sie auf deinen Plan, dessen Halte nummeriert auf der Karte stehen." } },
	{ id = 180, module = "lodestar",
		en = { "Lodestar: your plan beside the map", "Plan above the big map's right pane lists every stop numbered as on the map, the done ones ticked: hover one to light it on the map, click to go there, drag a quest to reorder. Each number on the map shows what it is: ! pick up, ? turn in, a dot an objective, explained under the map." },
		de = { "Lodestar: dein Plan neben der Karte", "Plan über der rechten Leiste der großen Karte listet jede Station, nummeriert wie auf der Karte, die erledigten abgehakt: Fahr über eine, um sie auf der Karte hervorzuheben, klick, um dorthin zu gehen, zieh eine Quest, um sie umzusortieren. Jede Zahl auf der Karte zeigt, was sie ist: ! annehmen, ? abgeben, ein Punkt ein Ziel, erklärt unter der Karte." } },
	{ id = 181, module = "lodestar",
		en = { "Lodestar: the companion stays open", "Escape no longer closes the companion, like the Bestiary's small window: its X or /lodestar does. Its plan part says which stop you're at (\"Stop 3 of 9\", as the Plan tab does), and the numbers on its small map show what they are: ! pick up, ? turn in, a dot an objective." },
		de = { "Lodestar: Begleiter bleibt offen", "Escape schließt den Begleiter nicht mehr, wie das kleine Fenster des Bestiariums: sein X oder /lodestar schließt ihn. Sein Planteil sagt, bei welcher Station du bist (\"Station 3 von 9\", wie der Tab Plan), und die Zahlen auf seiner kleinen Karte zeigen, was sie sind: ! annehmen, ? abgeben, ein Punkt ein Ziel." } },
	{ id = 182, module = "lodestar",
		en = { "Lodestar: the map's ! by difficulty", "On the big map every ! to pick up has its difficulty's colour, as the levels in the lists: green easy, yellow right for you, orange hard, red far too hard (grey ones were grey already). A yellow ! no longer hides a quest far above you." },
		de = { "Lodestar: ! der Karte nach Schwierigkeit", "Auf der großen Karte hat jedes ! zum Annehmen die Farbe seiner Schwierigkeit, wie die Level in den Listen: grün leicht, gelb passend für dich, orange schwer, rot viel zu schwer (graue waren schon grau). Ein gelbes ! versteckt keine Quest mehr, die weit über dir liegt." } },
	{ id = 183, module = "chronicle",
		en = { "Chronicle: friends by level", "The Friends page lists who's online and who isn't by level, the highest first, and by name where the level is the same. You're in Online now too, marked (you): a click opens your graphs." },
		de = { "Chronicle: Freunde nach Level", "Die Seite Freunde listet, wer online ist und wer nicht, nach Level, das höchste zuerst, und bei gleichem Level nach Namen. Du stehst auch unter Online, markiert mit (du): ein Klick öffnet deine Graphen." } },
	{ id = 184, module = "lodestar",
		en = { "Lodestar: a slimmer companion with tabs", "The companion (/lodestar) is now a slim window like the Bestiary's, only as tall as what it shows, without a scroll bar. Small tabs along its top keep apart what doesn't belong together: Now (the quest you're on with its objectives, turn-in and map), Next (what to pick up nearby) and Plan (while you have one: your next stops with their own map). It remembers your tab. A long list ends in \"and N more\", which opens the big window; so does the star at its top." },
		de = { "Lodestar: schlanker Begleiter mit Tabs", "Der Begleiter (/lodestar) ist jetzt ein schlankes Fenster wie das kleine Fenster des Bestiary, nur so hoch wie sein Inhalt, ohne Scrollleiste. Kleine Tabs oben trennen, was nicht zusammengehört: Jetzt (die Quest, an der du bist, mit Zielen, Abgabe und Karte), Als Nächstes (was du in der Nähe annehmen kannst) und Plan (wenn du einen hast: deine nächsten Stationen mit eigener Karte). Er merkt sich deinen Tab. Eine lange Liste endet mit \"und N weitere\", das öffnet das große Fenster; der Stern oben auch." } },
	{ id = 185, module = "lodestar",
		en = { "Lodestar: objective areas you can see", "The companion's small map fills each objective area in gold under its glow, as the big map does: on light ground the areas were all but invisible." },
		de = { "Lodestar: sichtbare Zielgebiete", "Die kleine Karte des Begleiters füllt jedes Zielgebiet golden unter seinem Schein, wie die große Karte: auf hellem Boden waren die Gebiete kaum zu sehen." } },
	{ id = 186, module = "general",
		en = { "One minimap button for LefthyTools", "The modules' minimap buttons are combined into one LefthyTools button: a click opens a list with each module's button and its name (they work as before), right-click opens the settings. Settings, General: Combine minimap buttons (on by default) puts them back on the edge one by one." },
		de = { "Ein Minimap-Button für LefthyTools", "Die Minimap-Buttons der Module sind in einem LefthyTools-Button zusammengefasst: ein Klick öffnet eine Liste mit dem Button jedes Moduls und seinem Namen (sie funktionieren wie bisher), Rechtsklick öffnet die Einstellungen. Einstellungen, Allgemein: Minimap-Buttons zusammenfassen (standardmäßig an) stellt sie wieder einzeln an den Rand." } },
	{ id = 187, module = "lodestar",
		en = { "Lodestar: quest levels on quest givers", "Pointing at a quest giver, the Lodestar lines show each quest's level with its title, in its difficulty colour: \"starts [17] Raptor Horns\"." },
		de = { "Lodestar: Questlevel bei Questgebern", "Zeigst du auf einen Questgeber, nennen die Lodestar-Zeilen das Level jeder Quest mit ihrem Titel, in der Farbe ihrer Schwierigkeit: \"vergibt [17] Raptorhörner\"." } },
	{ id = 188, module = "lodestar",
		en = { "Lodestar: a quest's parts aren't a chain", "Quests you take while another is in your log and that give an item it needs (The Warsong Reports' three updates, the Green Hills of Stranglethorn's chapters) are no longer shown as steps after it: its objectives say which quest gives each item." },
		de = { "Lodestar: Teile einer Quest", "Quests, die du annimmst, während eine andere in deinem Log ist, und die einen Gegenstand für sie geben (die drei Berichte von Die Kriegshymnenberichte, die Kapitel von Die grünen Hügel des Schlingendorntals), erscheinen nicht mehr als Schritte danach: ihre Ziele sagen, welche Quest jeden Gegenstand gibt." } },
	-- New entries go here, at the end.
}
